const fs=require('fs'),ts=require('typescript'),assert=require('assert/strict'),{createClient}=require('@supabase/supabase-js');
const selection=require('../src/data/curated-best-sellers.json');const moduleValue={exports:{}};new Function('require','module','exports',ts.transpileModule(fs.readFileSync('src/lib/store/external-best-sellers.ts','utf8'),{compilerOptions:{module:1,target:9,esModuleInterop:true}}).outputText)(n=>{if(n==='@/data/curated-best-sellers.json')return selection;throw Error(n)},moduleValue,moduleValue.exports);const {sortExternalBestSellers,externalBestSellerRank}=moduleValue.exports;
assert.equal(selection.items.length,selection.skus.length);assert.equal(new Set(selection.skus).size,selection.skus.length);assert.equal(externalBestSellerRank('not-ranked'),null);assert.equal(externalBestSellerRank(selection.skus[0]),1);
const pool=[{sku:'unknown-first'},{sku:selection.skus[1]},{sku:'unknown-last'},{sku:selection.skus[0]}];assert.deepEqual(sortExternalBestSellers(pool).map(x=>x.sku),[selection.skus[0],selection.skus[1],'unknown-first','unknown-last']);assert.equal(pool[0].sku,'unknown-first');pool[3].sold_out=true;assert.equal(sortExternalBestSellers(pool).at(-1).sku,selection.skus[0]);
