for(const line of fs.readFileSync('.env.local','utf8').split(/\r?\n/)){const m=line.match(/^([A-Z0-9_]+)=(.*)$/);if(m)process.env[m[1]]??=m[2].replace(/^['"]|['"]$/g,'');}
const db=createClient(process.env.NEXT_PUBLIC_SUPABASE_URL,process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,{auth:{persistSession:false}});
(async()=>{const base=()=>db.from('products').select('id,sku,name,brand,created_at').eq('status','active').is('deleted_at',null);const ranked=()=>base().order('sold_out',{ascending:true}).order('external_best_rank',{ascending:true,nullsFirst:false}).order('created_at',{ascending:false}).order('id',{ascending:false});const [first,second,brand,latest]=await Promise.all([ranked().range(0,47),ranked().range(48,95),ranked().eq('brand','MEDICUBE').range(0,47),base().order('created_at',{ascending:false}).order('id',{ascending:false}).range(0,47)]);for(const response of [first,second,brand,latest])if(response.error)throw response.error;
const privateRead=await db.from('products').select('wholesale_price').limit(1);assert(privateRead.error,'Anonymous wholesale price access must remain denied');
const all=[...first.data,...second.data];assert.equal(new Set(all.map(x=>x.id)).size,all.length);assert.deepEqual(all.slice(0,selection.skus.length).map(x=>x.sku),selection.skus);const medSkus=selection.items.filter(item=>item.name.toLowerCase().includes('medicube')).map(item=>item.sku);assert.deepEqual(brand.data.slice(0,medSkus.length).map(x=>x.sku),medSkus);assert.notEqual(latest.data[0].id,first.data[0].id);assert(!JSON.stringify(first.data).includes('wholesale_price'));
fs.writeFileSync('../../outputs/medicube-update-20261016/ranking-verification.json',JSON.stringify({priorityProducts:selection.skus.length,firstPageSkus:first.data.map(x=>x.sku),secondPageSkus:second.data.map(x=>x.sku),medicubePriority:medSkus.length,latestFirstSku:latest.data[0].sku,duplicateProducts:0,guestPricesExposed:false},null,2));console.log('PASS external evidence data, non-mutating availability order, anonymous database ordering across pages, brand filter, distinct latest order and guest price isolation.');
const rows=JSON.parse(fs.readFileSync('../../outputs/medicube-update-20261016/source.json')).values.slice(2).filter(r=>r[3]&&r[7]);const readback=JSON.parse(fs.readFileSync('../../outputs/medicube-update-20261016/readback.json'));assert.equal(new Set(rows.map(r=>String(r[1]).trim())).size,readback.length);for(const row of rows){const p=readback.find(x=>x.barcode===String(row[1]).trim());assert(p);assert.equal(p.name,String(row[3]).trim());assert.equal(+p.wholesale_price,+String(row[7]).replace(/[₩,\s]/g,''));assert.equal(p.moq,+row[5]);if(p.status==='active'){assert(+p.compare_at_price>0);assert(p.image_url&&!p.needs_image);}}
console.log('PASS all 201 supplier SKUs present; exact names, barcodes, supply prices and MOQ; public products have both prices and a checked image.');
})().catch(e=>{console.error(e.message);process.exitCode=1;});
